import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    for _ in range(T):
        try:
            N = int(next(iterator))
            P = []
            for _ in range(N):
                P.append(int(next(iterator)))
        except StopIteration:
            break

        operations = []
        total_cost = 0

        current_P = P[:]

        for pos in range(N):
            target_value = pos + 1
            if current_P[pos] == target_value:
                continue

            target_idx = -1
            for k in range(pos, N):
                if current_P[k] == target_value:
                    target_idx = k
                    break

            if target_idx == -1:
                continue

            dist = abs(target_idx - pos)
            total_cost += dist
            operations.append((pos + 1, target_idx + 1))

            current_P[pos], current_P[target_idx] = current_P[target_idx], current_P[pos]

        print(total_cost)
        print(len(operations))
        for i, j in operations:
            print(f"{i} {j}")

if __name__ == "__main__":
    solve()
